// WF04 -> canonical raw_market_records (Stage 3 closure, DEC-148). WF04 is the WEBSITE SOURCE ADAPTER:
// transport (Firecrawl) + cleaning + source metadata/evidence. It emits ONE canonical, WF16/WF08-compatible
// raw record per successfully scraped URL with analysis_status='pending'. WF08 is the SINGLE semantic owner
// and consumes this record exactly once; WF04's own extraction is kept here as SOURCE HINTS/evidence
// (service_hint/competitor_name/offer_text), never as final analyzer authority. No external calls.
function str(v){return v==null?'':String(v).trim();}
function low(v){return str(v).toLowerCase();}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
function domainOf(u){u=str(u).toLowerCase();var m=u.match(/^https?:\/\/([^\/?#]+)/);var h=m?m[1]:'';return h.replace(/^www\./,'');}
function brandFromDomain(d){d=str(d).replace(/^www\./,'').split('.')[0];if(!d)return '';return d.charAt(0).toUpperCase()+d.slice(1);}
const r=$json;
const route=low(r.route);const ps=low(r.processing_status);const pm=low(r.parse_method);
const src=str(r.source_url);
if(!src) return []; // no URL => nothing was scraped; no canonical record
let sourceRunId='';try{sourceRunId=str($('Set URL List').first().json.run_id);}catch(e){}
if(!sourceRunId)sourceRunId=str(r.run_id);
let agentReq='';try{agentReq=str($('Set URL List').first().json.agent_request_id);}catch(e){}
if(!agentReq)agentReq=str(r.agent_request_id)||('wf04_req_'+sourceRunId.replace(/^firecrawl_/,''));
const stamp=sourceRunId.replace(/^firecrawl_/,'')||moscowStamp();
const workflowRunId='wf04_'+stamp;
const idx=Number(r.batch_index)||0;
const sourceRecordId='wf04_rec_'+stamp+'_'+idx;
const domain=domainOf(src);
const text=cut(str(r.text_context),4000);
let company=str(r.company_name);
if(!company||/^конкурент без бренда$/i.test(company)){var bd=brandFromDomain(domain);if(bd)company=bd;}
const title=company||domain;
// quality gate (mirrors the snapshot logic): primary success=healthy; repaired/deterministic-fallback=degraded;
// transport/parse failure or no page evidence=quarantined.
const hasEvidence=(text.length>=30)||str(r.offer_text)!=='';
let quality_status='healthy';var qflags=[];
if(ps==='technical_error'||route==='technical_errors'||!hasEvidence){quality_status='quarantined';qflags.push('no_page_evidence');}
else if(pm==='deterministic_competitor_fallback'||r.repair_used===true||low(r.repair_status)==='failed_fallback'){quality_status='degraded';qflags.push('deterministic_fallback');}
const isCompetitor=(low(r.entity_type)==='competitor');
const report_eligible=(quality_status==='healthy'&&isCompetitor);
const review_status=(quality_status==='healthy'?'confirmed':'pending');
const recordTypeHint=isCompetitor?'competitor_activity':(low(r.entity_type)==='irrelevant'?'irrelevant':'market_signal');
const repair_calls=(r.repair_used===true||(low(r.repair_status)&&low(r.repair_status)!==''))?1:0;
return [{ json: {
  record_id:sourceRecordId,
  source_record_id:sourceRecordId,
  agent_request_id:agentReq,
  source_run_id:sourceRunId,
  run_id:sourceRunId,
  workflow_run_id:workflowRunId,
  data_mode:'live',
  created_at:str(r.created_at)||moscowIsoNow(),
  source_type:'scraped_web',
  platform:'website',
  source_url:src,
  post_url:src,
  exact_evidence_url:(quality_status!=='quarantined'),
  profile_url:'',
  profile_name:company,
  author_handle:'',
  published_at:str(r.published_at),
  region_hint:str(r.region),
  service_hint:low(r.service_type)||'unknown',
  title:title,
  description:cut(text,800),
  text_context:text,
  comment_text:'',
  contact_public:str(r.contact_public),
  dedup_key:low(r.platform||'website')+'::scraped_web::'+(domain||sourceRecordId),
  record_type_hint:recordTypeHint,
  touchpoint_type:'competitor_website',
  is_detail:true,
  detail_fetch_required:false,
  placeholder_title:false,
  is_valid_listing:(quality_status!=='quarantined'),
  competitor_related:isCompetitor,
  competitor_name:isCompetitor?company:'',
  interest_topic:str(r.detected_need),
